#!/usr/bin/env python3
from ta_emss import ta_emss
import time

CELL_ID_START = 2
RUN_NUMBER = 15

def filter_nrcell_list(nrcell_list, min_cell_id):
    filtered_list = []
    for cell in nrcell_list:
        cell_number = int(cell.split('-')[1])
        if cell_number >= min_cell_id:
            filtered_list.append(cell)
    return filtered_list


if __name__ == "__main__":

    emss1 = ta_emss()
    emss1.setup_emss(user='vcu1', bts_ip='192.168.100.129', oam_ip='192.168.100.1/24', alias='cu1', logging=False,
                     debug_fbox=False)

    print("---------------------------------------------------------")
    print("Start time:", time.strftime("%Y-%m-%d %H:%M:%S", time.localtime()))
    test_start_time = time.time()

    nrcell_objects_list = emss1.get_existing_objects_of_given_type(type_of_objects="NRCELL")
    nrcell_objects_list = filter_nrcell_list(nrcell_objects_list, CELL_ID_START)
    selected_param_from_ccn = []

    for run in range(RUN_NUMBER):
        print("---------------------------------------------------------")
        print(f"Run {run + 1} of {RUN_NUMBER}")
        print("---------------------------------------------------------")
        print("Resetting VCU...")
        emss1.reset_enb()
        print("Waiting for enabled NRCELLs state...")
        start_time = time.time()
        while True:
            ccn_message = emss1.get_incoming_ccn_message(object_name='NRCELL')
            for object_dict in ccn_message:
                if 'distName' in object_dict and 'parameters' in object_dict and 'operationalState' in object_dict[
                    'parameters'] and object_dict['parameters']['operationalState'] == 'enabled':
                    selected_param_from_ccn.append({
                        'distName': object_dict['distName'],
                        'operationalState': object_dict['parameters']['operationalState']})

            short_nrcell_list = [item['distName'].split('/')[-1] for item in selected_param_from_ccn]

            sorted_list_all_cells = sorted(nrcell_objects_list)
            sorted_list_cells_enabled = sorted(short_nrcell_list)
            if sorted_list_all_cells == sorted_list_cells_enabled:
                selected_param_from_ccn = []
                time.sleep(3)
                break
        end_time = time.time()
        elapsed_time = end_time - start_time
        print("All NRCELLs are now OPERATIONAL/enabled.")
        print(f"Waiting time for OPERATIONAL/enabled: {elapsed_time:.2f} seconds")
    test_end_time = time.time()
    total_test_duration = test_end_time - test_start_time
    total_test_minutes = total_test_duration / 60

    print("---------------------------------------------------------")
    print("End time:", time.strftime("%Y-%m-%d %H:%M:%S", time.localtime()))
    print("---------------------------------------------------------")
    print(f"Total test duration: {total_test_minutes:.2f} minutes")
    print("---------------------------------------------------------")
